type PostSummary = Awaited<ReturnType<typeof fetchPosts>>[number]

import {Config, Field, type Infer} from 'alinea'

export const TextBlock = Config.type('Text', {
  fields: {
    body: Field.richText('Body')
  }
})

export const ImageBlock = Config.type('Image', {
  fields: {
    image: Field.image('Image')
  }
})

export const BlogPost = Config.document('Blog post', {
  fields: {
    publishDate: Field.date('Publish date'),
    author: Field.entry('Author'),
    blocks: Field.list('Blocks', {
      schema: {Text: TextBlock, Image: ImageBlock}
    })
  }
})

// The fields of a blog post, as a query returns them
export type BlogPost = Infer<typeof BlogPost>
// The same, plus the entry fields (_id, _type, _url, ...)
export type BlogPostEntry = Infer.Entry<typeof BlogPost>
// A row of the list field, with _id, _index and _type
export type TextBlock = Infer.ListItem<typeof TextBlock, 'Text'>
// The value of one field
export type Blocks = BlogPost['blocks']

import type {Blocks} from '@/schema/BlogPost'

export function BlocksView({blocks}: {blocks: Blocks}) {
  return (
    <>
      {blocks.map(block => {
        switch (block._type) {
          case 'Text':
            return <TextBlockView key={block._id} block={block} />
          case 'Image':
            return <img key={block._id} src={block.image?.src} alt="" />
        }
      })}
    </>
  )
}
